=== FILE: axil_timer.v ===
// axil_timer: 32-bit down-counting timer with one-shot and periodic modes
// and a level interrupt, behind an AXI4-Lite subordinate port.
// Implements interface_spec.md following microarchitecture.md.
module axil_timer #(
    parameter integer ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,
    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,
    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,
    output reg  [1:0]            s_axil_bresp,
    output reg                   s_axil_bvalid,
    input  wire                  s_axil_bready,
    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,
    output reg  [31:0]           s_axil_rdata,
    output reg  [1:0]            s_axil_rresp,
    output reg                   s_axil_rvalid,
    input  wire                  s_axil_rready,
    output wire                  irq
);

    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;

    localparam [1:0] IDX_CTRL   = 2'd0;
    localparam [1:0] IDX_LOAD   = 2'd1;
    localparam [1:0] IDX_COUNT  = 2'd2;
    localparam [1:0] IDX_STATUS = 2'd3;

    // ------------------------------------------------------------------
    // State
    // ------------------------------------------------------------------
    // Write-channel holding state (a half that arrived alone)
    reg                  aw_held;
    reg [ADDR_WIDTH-1:0] aw_addr_q;
    reg                  w_held;
    reg [31:0]           w_data_q;
    reg [3:0]            w_strb_q;

    // Timer state
    reg        en;
    reg        ie;
    reg        mode;
    reg        expired;
    reg [31:0] load;
    reg [31:0] count;

    // ------------------------------------------------------------------
    // Channel handshakes (READY depends on flops only)
    // ------------------------------------------------------------------
    assign s_axil_awready = !aw_held && !s_axil_bvalid;
    assign s_axil_wready  = !w_held  && !s_axil_bvalid;
    assign s_axil_arready = !s_axil_rvalid;

    wire aw_hs    = s_axil_awvalid && s_axil_awready;
    wire w_hs     = s_axil_wvalid  && s_axil_wready;
    wire do_write = (aw_held || aw_hs) && (w_held || w_hs);
    wire ar_hs    = s_axil_arvalid && s_axil_arready;

    // ------------------------------------------------------------------
    // Write decode
    // ------------------------------------------------------------------
    wire [ADDR_WIDTH-1:0] wr_addr = aw_held ? aw_addr_q : s_axil_awaddr;
    wire [31:0]           wr_data = w_held  ? w_data_q  : s_axil_wdata;
    wire [3:0]            wr_strb = w_held  ? w_strb_q  : s_axil_wstrb;

    wire [31:0] wr_addr_ext = {{(32-ADDR_WIDTH){1'b0}}, wr_addr};
    wire        wr_mapped   = (wr_addr_ext[1:0] == 2'b00) && (wr_addr_ext[31:4] == 28'd0);
    wire [1:0]  wr_idx      = wr_addr_ext[3:2];
    wire        wr_ok       = wr_mapped && (wr_idx != IDX_COUNT);

    wire wr_ctrl   = do_write && wr_mapped && (wr_idx == IDX_CTRL)   && wr_strb[0];
    wire wr_load   = do_write && wr_mapped && (wr_idx == IDX_LOAD);
    wire wr_status = do_write && wr_mapped && (wr_idx == IDX_STATUS) && wr_strb[0];

    wire [31:0] strb_mask   = {{8{wr_strb[3]}}, {8{wr_strb[2]}},
                               {8{wr_strb[1]}}, {8{wr_strb[0]}}};
    wire [31:0] load_merged = (load & ~strb_mask) | (wr_data & strb_mask);

    // ------------------------------------------------------------------
    // Read decode
    // ------------------------------------------------------------------
    wire [31:0] rd_addr_ext = {{(32-ADDR_WIDTH){1'b0}}, s_axil_araddr};
    wire        rd_mapped   = (rd_addr_ext[1:0] == 2'b00) && (rd_addr_ext[31:4] == 28'd0);
    wire [1:0]  rd_idx      = rd_addr_ext[3:2];

    reg [31:0] rd_value;
    always @* begin
        case (rd_idx)
            IDX_CTRL:   rd_value = {29'd0, mode, ie, en};
            IDX_LOAD:   rd_value = load;
            IDX_COUNT:  rd_value = count;
            IDX_STATUS: rd_value = {31'd0, expired};
            default:    rd_value = 32'd0;
        endcase
        if (!rd_mapped) begin
            rd_value = 32'd0;
        end
    end

    // ------------------------------------------------------------------
    // Timer end of count (LOAD of 0 counts as 1)
    // ------------------------------------------------------------------
    wire count_end = en && (count <= 32'd1);

    // ------------------------------------------------------------------
    // Write channel
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held       <= 1'b0;
            aw_addr_q     <= {ADDR_WIDTH{1'b0}};
            w_held        <= 1'b0;
            w_data_q      <= 32'd0;
            w_strb_q      <= 4'd0;
            s_axil_bvalid <= 1'b0;
            s_axil_bresp  <= RESP_OKAY;
        end else begin
            if (do_write) begin
                aw_held <= 1'b0;
                w_held  <= 1'b0;
            end else begin
                if (aw_hs) begin
                    aw_held   <= 1'b1;
                    aw_addr_q <= s_axil_awaddr;
                end
                if (w_hs) begin
                    w_held   <= 1'b1;
                    w_data_q <= s_axil_wdata;
                    w_strb_q <= s_axil_wstrb;
                end
            end

            if (do_write) begin
                s_axil_bvalid <= 1'b1;
                s_axil_bresp  <= wr_ok ? RESP_OKAY : RESP_SLVERR;
            end else if (s_axil_bready) begin
                s_axil_bvalid <= 1'b0;
            end
        end
    end

    // ------------------------------------------------------------------
    // Read channel
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            s_axil_rvalid <= 1'b0;
            s_axil_rdata  <= 32'd0;
            s_axil_rresp  <= RESP_OKAY;
        end else if (ar_hs) begin
            s_axil_rvalid <= 1'b1;
            s_axil_rdata  <= rd_value;
            s_axil_rresp  <= rd_mapped ? RESP_OKAY : RESP_SLVERR;
        end else if (s_axil_rready) begin
            s_axil_rvalid <= 1'b0;
        end
    end

    // ------------------------------------------------------------------
    // Timer: priorities fall out of last-assignment-wins
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            en      <= 1'b0;
            ie      <= 1'b0;
            mode    <= 1'b0;
            expired <= 1'b0;
            load    <= 32'd0;
            count   <= 32'd0;
        end else begin
            // 1. Count step
            if (en) begin
                if (count_end) begin
                    if (mode) begin
                        count <= load;
                    end else begin
                        count <= 32'd0;
                        en    <= 1'b0;
                    end
                end else begin
                    count <= count - 32'd1;
                end
            end

            // 2. EXPIRED: clear, then set (a count end beats a clear)
            if (wr_status && wr_data[0]) begin
                expired <= 1'b0;
            end
            if (count_end) begin
                expired <= 1'b1;
            end

            // 3. CTRL write (wins over the count step for en and count)
            if (wr_ctrl) begin
                ie   <= wr_data[1];
                mode <= wr_data[2];
                if (wr_data[0]) begin
                    en    <= 1'b1;
                    count <= load;
                end else begin
                    en <= 1'b0;
                end
            end

            // 4. LOAD write, byte merged
            if (wr_load) begin
                load <= load_merged;
            end
        end
    end

    assign irq = expired & ie;

endmodule
=== END FILE ===
