// Testbench top for axil_timer: runs one lane at ADDR_WIDTH 4 and one at
// ADDR_WIDTH 8, then prints the verdict once and finishes.
module axil_timer_tb;

    reg aclk = 1'b0;
    always #5 aclk = ~aclk;

    wire        done4;
    wire        done8;
    wire [31:0] passed4;
    wire [31:0] failed4;
    wire [31:0] passed8;
    wire [31:0] failed8;

    reg [8*64-1:0] nonce;
    reg [31:0]     extra_fail;
    integer        waited;

    axil_timer_lane #(.AW(4)) lane_aw4 (
        .aclk   (aclk),
        .done   (done4),
        .passed (passed4),
        .failed (failed4)
    );

    axil_timer_lane #(.AW(8)) lane_aw8 (
        .aclk   (aclk),
        .done   (done8),
        .passed (passed8),
        .failed (failed8)
    );

    initial begin
        nonce      = {(8*64){1'b0}};
        extra_fail = 32'd0;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) begin
            nonce = {(8*64){1'b0}};
        end
        waited = 0;
        while (((done4 !== 1'b1) || (done8 !== 1'b1)) && (waited < 200000)) begin
            @(posedge aclk);
            waited = waited + 1;
        end
        #2;
        if ((done4 !== 1'b1) || (done8 !== 1'b1)) begin
            extra_fail = 32'd1;
            $error("testbench timeout: lanes did not finish");
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce,
                 passed4 + passed8, failed4 + failed8 + extra_fail);
        $finish;
    end

endmodule
=== END FILE ===
=== FILE: axil_timer_lane.v ===
// One test lane for axil_timer: a DUT at ADDR_WIDTH = AW and a directed,
// self-checking sequence. Every failed check is reported with $error.
// Convention: all stimulus is driven and all outputs sampled 1 time unit
// after a rising edge; "edge k" is the k-th rising edge, and cyc reads k
// at the sampling point after edge k.
module axil_timer_lane #(
    parameter integer AW = 4
) (
    input  wire        aclk,
    output reg         done,
    output reg  [31:0] passed,
    output reg  [31:0] failed
);

    localparam [1:0] OKAY   = 2'b00;
    localparam [1:0] SLVERR = 2'b10;

    localparam [7:0] A_CTRL   = 8'h00;
    localparam [7:0] A_LOAD   = 8'h04;
    localparam [7:0] A_COUNT  = 8'h08;
    localparam [7:0] A_STATUS = 8'h0C;

    reg           aresetn;
    reg  [AW-1:0] awaddr;
    reg           awvalid;
    wire          awready;
    reg  [31:0]   wdata;
    reg  [3:0]    wstrb;
    reg           wvalid;
    wire          wready;
    wire [1:0]    bresp;
    wire          bvalid;
    reg           bready;
    reg  [AW-1:0] araddr;
    reg           arvalid;
    wire          arready;
    wire [31:0]   rdata;
    wire [1:0]    rresp;
    wire          rvalid;
    reg           rready;
    wire          irq;

    axil_timer #(.ADDR_WIDTH(AW)) dut (
        .aclk           (aclk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (awaddr),
        .s_axil_awvalid (awvalid),
        .s_axil_awready (awready),
        .s_axil_wdata   (wdata),
        .s_axil_wstrb   (wstrb),
        .s_axil_wvalid  (wvalid),
        .s_axil_wready  (wready),
        .s_axil_bresp   (bresp),
        .s_axil_bvalid  (bvalid),
        .s_axil_bready  (bready),
        .s_axil_araddr  (araddr),
        .s_axil_arvalid (arvalid),
        .s_axil_arready (arready),
        .s_axil_rdata   (rdata),
        .s_axil_rresp   (rresp),
        .s_axil_rvalid  (rvalid),
        .s_axil_rready  (rready),
        .irq            (irq)
    );

    // ------------------------------------------------------------------
    // Edge counter and irq rise monitor
    // ------------------------------------------------------------------
    reg [31:0] cyc        = 32'd0;
    reg        irq_prev   = 1'b0;
    reg [31:0] rise_edge  = 32'd0;
    reg [31:0] rise_count = 32'd0;

    always @(posedge aclk) begin
        cyc <= cyc + 32'd1;
    end

    // Sampled at edge k+1, irq is its value after edge k and cyc reads k.
    always @(posedge aclk) begin
        if (irq && !irq_prev) begin
            rise_edge  <= cyc;
            rise_count <= rise_count + 32'd1;
        end
        irq_prev <= irq;
    end

    reg [31:0] last_eff;

    // ------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------
    function [AW-1:0] trunc;
        input [7:0] a;
        begin
            trunc = a[AW-1:0];
        end
    endfunction

    task tick;
        begin
            @(posedge aclk);
            #1;
        end
    endtask

    task idle(input integer cycles);
        begin
            repeat (cycles) tick;
        end
    endtask

    task chk1(input integer id, input got, input exp);
        begin
            if (got === exp) begin
                passed = passed + 32'd1;
            end else begin
                failed = failed + 32'd1;
                $error("lane AW=%0d check %0d at edge %0d: got %b, expected %b",
                       AW, id, cyc, got, exp);
            end
        end
    endtask

    task chk2(input integer id, input [1:0] got, input [1:0] exp);
        begin
            if (got === exp) begin
                passed = passed + 32'd1;
            end else begin
                failed = failed + 32'd1;
                $error("lane AW=%0d check %0d at edge %0d: got %b, expected %b",
                       AW, id, cyc, got, exp);
            end
        end
    endtask

    task chk32(input integer id, input [31:0] got, input [31:0] exp);
        begin
            if (got === exp) begin
                passed = passed + 32'd1;
            end else begin
                failed = failed + 32'd1;
                $error("lane AW=%0d check %0d at edge %0d: got 0x%08h, expected 0x%08h",
                       AW, id, cyc, got, exp);
            end
        end
    endtask

    task wait_until(input [31:0] target);
        begin
            if (cyc > target) begin
                failed = failed + 32'd1;
                $error("lane AW=%0d: wait_until(%0d) called late at edge %0d", AW, target, cyc);
            end
            while (cyc < target) tick;
        end
    endtask

    task wait_rise(input [31:0] base_n, input integer limit);
        integer k;
        begin
            k = 0;
            while ((rise_count == base_n) && (k < limit)) begin
                tick;
                k = k + 1;
            end
        end
    endtask

    // order: 0 = AW and W together, 1 = AW first, 2 = W first.
    // gap: cycles the second half waits. bdelay: cycles BREADY is held low.
    // eff: the edge on which the write took effect (both halves accepted).
    task axi_write(
        input  [7:0]   addr,
        input  [31:0]  data,
        input  [3:0]   strb,
        input  integer order,
        input  integer gap,
        input  integer bdelay,
        output [1:0]   resp,
        output [31:0]  eff
    );
        reg     aw_done;
        reg     w_done;
        reg     aw_fire;
        reg     w_fire;
        integer k;
        begin
            aw_done = 1'b0;
            w_done  = 1'b0;
            k       = 0;
            bready  = 1'b0;
            awaddr  = trunc(addr);
            wdata   = data;
            wstrb   = strb;
            while (!(aw_done && w_done) && (k < 64)) begin
                awvalid = !aw_done && ((order != 2) || (k >= gap));
                wvalid  = !w_done  && ((order != 1) || (k >= gap));
                aw_fire = awvalid && awready;
                w_fire  = wvalid && wready;
                tick;
                if (aw_fire) aw_done = 1'b1;
                if (w_fire)  w_done  = 1'b1;
                if (aw_done && !w_done) begin
                    chk1(9020, awready, 1'b0);
                    chk1(9021, wready, 1'b1);
                    chk1(9022, bvalid, 1'b0);
                end
                if (w_done && !aw_done) begin
                    chk1(9023, wready, 1'b0);
                    chk1(9024, awready, 1'b1);
                    chk1(9025, bvalid, 1'b0);
                end
                k = k + 1;
            end
            awvalid = 1'b0;
            wvalid  = 1'b0;
            eff     = cyc;
            chk1(9000, aw_done && w_done, 1'b1);
            chk1(9001, bvalid, 1'b1);
            chk1(9002, awready, 1'b0);
            chk1(9003, wready, 1'b0);
            resp = bresp;
            repeat (bdelay) begin
                tick;
                chk1(9004, bvalid, 1'b1);
                chk2(9005, bresp, resp);
                chk1(9006, awready, 1'b0);
                chk1(9007, wready, 1'b0);
            end
            bready = 1'b1;
            tick;
            bready = 1'b0;
            chk1(9008, bvalid, 1'b0);
            chk1(9009, awready, 1'b1);
            chk1(9010, wready, 1'b1);
        end
    endtask

    // rdelay: cycles RREADY is held low. acc: the edge the address was accepted.
    task axi_read(
        input  [7:0]   addr,
        input  integer rdelay,
        output [31:0]  data,
        output [1:0]   resp,
        output [31:0]  acc
    );
        reg     fire;
        integer k;
        begin
            araddr  = trunc(addr);
            arvalid = 1'b1;
            rready  = 1'b0;
            fire    = 1'b0;
            k       = 0;
            while (!fire && (k < 64)) begin
                fire = arready;
                tick;
                k = k + 1;
            end
            arvalid = 1'b0;
            acc     = cyc;
            chk1(9100, fire, 1'b1);
            chk1(9101, rvalid, 1'b1);
            chk1(9102, arready, 1'b0);
            data = rdata;
            resp = rresp;
            repeat (rdelay) begin
                tick;
                chk1(9103, rvalid, 1'b1);
                chk32(9104, rdata, data);
                chk2(9105, rresp, resp);
                chk1(9106, arready, 1'b0);
            end
            rready = 1'b1;
            tick;
            rready = 1'b0;
            chk1(9107, rvalid, 1'b0);
            chk1(9108, arready, 1'b1);
        end
    endtask

    task wr(input integer id, input [7:0] addr, input [31:0] data,
            input [3:0] strb, input [1:0] exp_resp);
        reg [1:0]  r_l;
        reg [31:0] e_l;
        begin
            axi_write(addr, data, strb, 0, 0, 0, r_l, e_l);
            chk2(id, r_l, exp_resp);
            last_eff = e_l;
        end
    endtask

    task rd(input integer id, input [7:0] addr, input [31:0] exp_data,
            input [1:0] exp_resp);
        reg [31:0] d_l;
        reg [1:0]  r_l;
        reg [31:0] a_l;
        begin
            axi_read(addr, 0, d_l, r_l, a_l);
            chk32(id, d_l, exp_data);
            chk2(id, r_l, exp_resp);
        end
    endtask

    // One-shot count timed to the cycle, EN self-clear, no second interrupt.
    task oneshot(input integer id, input [31:0] nload);
        reg [31:0] neff;
        reg [31:0] e_l;
        reg [31:0] b_l;
        reg [31:0] v_l;
        reg [31:0] a_l;
        reg [1:0]  r_l;
        begin
            neff = (nload == 32'd0) ? 32'd1 : nload;
            wr(id, A_LOAD, nload, 4'hF, OKAY);
            b_l = rise_count;
            wr(id + 1, A_CTRL, 32'h0000_0003, 4'hF, OKAY);
            e_l = last_eff;
            if (nload >= 32'd20) begin
                axi_read(A_COUNT, 0, v_l, r_l, a_l);
                chk32(id + 2, v_l, nload - (a_l - 32'd1 - e_l));
                chk2(id + 3, r_l, OKAY);
            end
            wait_rise(b_l, neff + 32'd20);
            chk32(id + 4, rise_edge, e_l + neff);
            chk32(id + 5, rise_count, b_l + 32'd1);
            rd(id + 6, A_CTRL, 32'h0000_0002, OKAY);
            rd(id + 7, A_COUNT, 32'h0000_0000, OKAY);
            rd(id + 8, A_STATUS, 32'h0000_0001, OKAY);
            chk1(id + 9, irq, 1'b1);
            wr(id + 10, A_STATUS, 32'h0000_0001, 4'hF, OKAY);
            chk1(id + 11, irq, 1'b0);
            rd(id + 12, A_STATUS, 32'h0000_0000, OKAY);
            idle(3 * neff + 10);
            chk32(id + 13, rise_count, b_l + 32'd1);
            chk1(id + 14, irq, 1'b0);
            rd(id + 15, A_COUNT, 32'h0000_0000, OKAY);
            rd(id + 16, A_CTRL, 32'h0000_0002, OKAY);
        end
    endtask

    // ------------------------------------------------------------------
    // Directed sequence
    // ------------------------------------------------------------------
    reg [31:0] e0;
    reg [31:0] e1;
    reg [31:0] t;
    reg [31:0] n;
    reg [31:0] base;
    reg [31:0] v;
    reg [31:0] a;
    reg [31:0] s;
    reg [31:0] f;
    reg [1:0]  r;

    initial begin
        done    = 1'b0;
        passed  = 32'd0;
        failed  = 32'd0;
        aresetn = 1'b0;
        awaddr  = {AW{1'b0}};
        awvalid = 1'b0;
        wdata   = 32'd0;
        wstrb   = 4'd0;
        wvalid  = 1'b0;
        bready  = 1'b0;
        araddr  = {AW{1'b0}};
        arvalid = 1'b0;
        rready  = 1'b0;

        // ---- T1: reset values ----
        tick; tick; tick;
        aresetn = 1'b1;
        chk1(100, awready, 1'b1);
        chk1(101, wready, 1'b1);
        chk1(102, arready, 1'b1);
        chk1(103, bvalid, 1'b0);
        chk1(104, rvalid, 1'b0);
        chk1(105, irq, 1'b0);
        rd(110, A_CTRL,   32'h0, OKAY);
        rd(111, A_LOAD,   32'h0, OKAY);
        rd(112, A_COUNT,  32'h0, OKAY);
        rd(113, A_STATUS, 32'h0, OKAY);

        // ---- T2: LOAD with partial strobes, both channel orders, backpressure ----
        axi_write(A_LOAD, 32'hFFFF_FFFF, 4'hF, 0, 0, 3, r, e0);
        chk2(200, r, OKAY);
        axi_read(A_LOAD, 4, v, r, a);
        chk32(201, v, 32'hFFFF_FFFF);
        chk2(202, r, OKAY);
        axi_write(A_LOAD, 32'h1234_5678, 4'b0001, 1, 2, 0, r, e0);
        chk2(203, r, OKAY);
        rd(204, A_LOAD, 32'hFFFF_FF78, OKAY);
        axi_write(A_LOAD, 32'hAABB_CCDD, 4'b0110, 2, 3, 5, r, e0);
        chk2(205, r, OKAY);
        rd(206, A_LOAD, 32'hFFBB_CC78, OKAY);
        axi_write(A_LOAD, 32'h1122_3344, 4'b1000, 1, 1, 1, r, e0);
        chk2(207, r, OKAY);
        rd(208, A_LOAD, 32'h11BB_CC78, OKAY);
        axi_write(A_LOAD, 32'hDEAD_BEEF, 4'b0000, 2, 1, 2, r, e0);
        chk2(209, r, OKAY);
        axi_read(A_LOAD, 3, v, r, a);
        chk32(210, v, 32'h11BB_CC78);
        chk2(211, r, OKAY);

        // ---- T3: a read and a write on the same clock ----
        awaddr = trunc(A_LOAD);
        wdata  = 32'h0BAD_F00D;
        wstrb  = 4'hF;
        araddr = trunc(A_LOAD);
        chk1(300, awready, 1'b1);
        chk1(301, wready, 1'b1);
        chk1(302, arready, 1'b1);
        awvalid = 1'b1;
        wvalid  = 1'b1;
        arvalid = 1'b1;
        tick;
        awvalid = 1'b0;
        wvalid  = 1'b0;
        arvalid = 1'b0;
        chk1(303, bvalid, 1'b1);
        chk2(304, bresp, OKAY);
        chk1(305, rvalid, 1'b1);
        chk32(306, rdata, 32'h11BB_CC78);
        chk2(307, rresp, OKAY);
        bready = 1'b1;
        rready = 1'b1;
        tick;
        bready = 1'b0;
        rready = 1'b0;
        chk1(308, bvalid, 1'b0);
        chk1(309, rvalid, 1'b0);
        rd(310, A_LOAD, 32'h0BAD_F00D, OKAY);

        // ---- T4: COUNT is read only ----
        wr(400, A_COUNT, 32'h0000_0055, 4'hF, SLVERR);
        rd(401, A_COUNT, 32'h0, OKAY);
        rd(402, A_CTRL, 32'h0, OKAY);

        // ---- T5: unaligned and unmapped addresses ----
        wr(500, 8'h01, 32'h0000_0007, 4'hF, SLVERR);
        wr(501, 8'h06, 32'hFFFF_FFFF, 4'hF, SLVERR);
        wr(502, 8'h0F, 32'h0000_0001, 4'hF, SLVERR);
        rd(503, 8'h05, 32'h0, SLVERR);
        rd(504, 8'h0E, 32'h0, SLVERR);
        rd(505, 8'h03, 32'h0, SLVERR);
        rd(506, A_CTRL, 32'h0, OKAY);
        rd(507, A_LOAD, 32'h0BAD_F00D, OKAY);
        rd(508, A_COUNT, 32'h0, OKAY);
        chk1(509, irq, 1'b0);
        if (AW > 4) begin
            wr(510, 8'h10, 32'h0000_0007, 4'hF, SLVERR);
            wr(511, 8'h14, 32'hFFFF_FFFF, 4'hF, SLVERR);
            wr(512, 8'h1C, 32'h0000_0001, 4'hF, SLVERR);
            wr(513, 8'hF4, 32'h1234_5678, 4'hF, SLVERR);
            rd(514, 8'h10, 32'h0, SLVERR);
            rd(515, 8'h14, 32'h0, SLVERR);
            rd(516, 8'h18, 32'h0, SLVERR);
            rd(517, 8'hFC, 32'h0, SLVERR);
            rd(518, A_CTRL, 32'h0, OKAY);
            rd(519, A_LOAD, 32'h0BAD_F00D, OKAY);
            rd(520, A_COUNT, 32'h0, OKAY);
            chk1(521, irq, 1'b0);
        end

        // ---- T6: CTRL write without wstrb[0] ----
        wr(600, A_CTRL, 32'h0000_0007, 4'b1110, OKAY);
        rd(601, A_CTRL, 32'h0, OKAY);
        idle(5);
        rd(602, A_COUNT, 32'h0, OKAY);
        chk1(603, irq, 1'b0);

        // ---- T7: one-shot counts timed to the cycle ----
        oneshot(700, 32'd5);
        oneshot(720, 32'd1);
        oneshot(740, 32'd0);
        oneshot(760, 32'd40);

        // ---- T8: interrupt enable on a pending expiry; STATUS clear rules ----
        wr(800, A_STATUS, 32'h1, 4'hF, OKAY);
        wr(801, A_LOAD, 32'd3, 4'hF, OKAY);
        wr(802, A_CTRL, 32'h0000_0001, 4'hF, OKAY);
        base = rise_count;
        idle(10);
        chk1(803, irq, 1'b0);
        chk32(804, rise_count, base);
        rd(805, A_STATUS, 32'h1, OKAY);
        rd(806, A_CTRL, 32'h0, OKAY);
        wr(807, A_CTRL, 32'h0000_0002, 4'hF, OKAY);
        e1 = last_eff;
        chk1(808, irq, 1'b1);
        chk32(809, rise_edge, e1);
        chk32(810, rise_count, base + 32'd1);
        wr(811, A_CTRL, 32'h0000_0000, 4'hF, OKAY);
        chk1(812, irq, 1'b0);
        rd(813, A_STATUS, 32'h1, OKAY);
        wr(814, A_STATUS, 32'h0, 4'hF, OKAY);
        rd(815, A_STATUS, 32'h1, OKAY);
        wr(816, A_STATUS, 32'hFFFF_FFFF, 4'b1110, OKAY);
        rd(817, A_STATUS, 32'h1, OKAY);
        wr(818, A_STATUS, 32'h1, 4'b0001, OKAY);
        rd(819, A_STATUS, 32'h0, OKAY);

        // ---- T9: periodic counts over several periods; clear on end edge; stop ----
        n = 32'd12;
        wr(1100, A_LOAD, n, 4'hF, OKAY);
        base = rise_count;
        wr(1101, A_CTRL, 32'h0000_0007, 4'hF, OKAY);
        e0 = last_eff;
        wait_rise(base, 40);
        chk32(1102, rise_edge, e0 + n);
        chk32(1103, rise_count, base + 32'd1);
        rd(1104, A_CTRL, 32'h0000_0007, OKAY);
        wr(1105, A_STATUS, 32'h1, 4'hF, OKAY);
        chk1(1106, irq, 1'b0);
        axi_read(A_COUNT, 0, v, r, a);
        chk32(1107, v, n - ((a - 32'd1 - e0) % n));
        chk2(1108, r, OKAY);
        wait_rise(base + 32'd1, 40);
        chk32(1110, rise_edge, e0 + 32'd2 * n);
        chk32(1111, rise_count, base + 32'd2);
        wr(1112, A_STATUS, 32'h1, 4'hF, OKAY);
        chk1(1113, irq, 1'b0);
        // A clear landing on the edge a count ends: the expiry is kept.
        t = e0 + 32'd3 * n;
        wait_until(t - 32'd1);
        axi_write(A_STATUS, 32'h1, 4'b0001, 0, 0, 0, r, e1);
        chk32(1114, e1, t);
        chk2(1115, r, OKAY);
        chk1(1116, irq, 1'b1);
        chk32(1117, rise_edge, t);
        chk32(1118, rise_count, base + 32'd3);
        rd(1119, A_STATUS, 32'h1, OKAY);
        wr(1120, A_STATUS, 32'h1, 4'hF, OKAY);
        chk1(1121, irq, 1'b0);
        wait_rise(base + 32'd3, 40);
        chk32(1122, rise_edge, e0 + 32'd4 * n);
        chk32(1123, rise_count, base + 32'd4);
        wr(1124, A_STATUS, 32'h1, 4'hF, OKAY);
        // Stop: COUNT freezes at the value the stop edge gives it.
        wr(1125, A_CTRL, 32'h0000_0006, 4'hF, OKAY);
        s = last_eff;
        chk1(1126, ((s - e0) % n) != 32'd0, 1'b1);
        f = n - ((s - e0) % n);
        rd(1127, A_COUNT, f, OKAY);
        idle(30);
        rd(1128, A_COUNT, f, OKAY);
        rd(1129, A_CTRL, 32'h0000_0006, OKAY);
        rd(1130, A_STATUS, 32'h0, OKAY);
        chk32(1131, rise_count, base + 32'd4);
        chk1(1132, irq, 1'b0);

        // ---- T10: restart mid-count (one-shot) ----
        wr(1200, A_LOAD, 32'd10, 4'hF, OKAY);
        base = rise_count;
        wr(1201, A_CTRL, 32'h0000_0003, 4'hF, OKAY);
        e0 = last_eff;
        idle(3);
        wr(1202, A_CTRL, 32'h0000_0003, 4'hF, OKAY);
        e1 = last_eff;
        chk1(1203, (e1 - e0) < 32'd10, 1'b1);
        wait_rise(base, 40);
        chk32(1204, rise_edge, e1 + 32'd10);
        chk32(1205, rise_count, base + 32'd1);
        idle(20);
        chk32(1206, rise_count, base + 32'd1);
        rd(1207, A_CTRL, 32'h0000_0002, OKAY);
        wr(1208, A_STATUS, 32'h1, 4'hF, OKAY);
        chk1(1209, irq, 1'b0);

        // ---- T11: restart landing on the edge a count ends ----
        wr(1300, A_LOAD, 32'd10, 4'hF, OKAY);
        base = rise_count;
        wr(1301, A_CTRL, 32'h0000_0003, 4'hF, OKAY);
        e0 = last_eff;
        t = e0 + 32'd10;
        wait_until(t - 32'd1);
        axi_write(A_CTRL, 32'h0000_0003, 4'b0001, 0, 0, 0, r, e1);
        chk32(1302, e1, t);
        chk2(1303, r, OKAY);
        chk1(1304, irq, 1'b1);
        chk32(1305, rise_edge, t);
        axi_read(A_COUNT, 0, v, r, a);
        chk32(1306, v, 32'd10 - (a - 32'd1 - t));
        rd(1307, A_CTRL, 32'h0000_0003, OKAY);
        wr(1308, A_STATUS, 32'h1, 4'hF, OKAY);
        chk1(1309, irq, 1'b0);
        wait_rise(base + 32'd1, 30);
        chk32(1310, rise_edge, t + 32'd10);
        chk32(1311, rise_count, base + 32'd2);
        rd(1312, A_CTRL, 32'h0000_0002, OKAY);
        wr(1313, A_STATUS, 32'h1, 4'hF, OKAY);

        // ---- T12: stop landing on the edge a periodic count ends ----
        wr(1400, A_LOAD, 32'd8, 4'hF, OKAY);
        base = rise_count;
        wr(1401, A_CTRL, 32'h0000_0007, 4'hF, OKAY);
        e0 = last_eff;
        t = e0 + 32'd8;
        wait_until(t - 32'd1);
        axi_write(A_CTRL, 32'h0000_0006, 4'b0001, 0, 0, 0, r, e1);
        chk32(1402, e1, t);
        chk1(1403, irq, 1'b1);
        rd(1404, A_CTRL, 32'h0000_0006, OKAY);
        rd(1405, A_COUNT, 32'd8, OKAY);
        idle(20);
        rd(1406, A_COUNT, 32'd8, OKAY);
        chk32(1407, rise_count, base + 32'd1);
        chk32(1408, rise_edge, t);
        wr(1409, A_STATUS, 32'h1, 4'hF, OKAY);
        chk1(1410, irq, 1'b0);

        // ---- T13: reset during a count, with a held write address ----
        wr(1500, A_LOAD, 32'd20, 4'hF, OKAY);
        base = rise_count;
        wr(1501, A_CTRL, 32'h0000_0003, 4'hF, OKAY);
        idle(5);
        awaddr = trunc(A_LOAD);
        chk1(1502, awready, 1'b1);
        awvalid = 1'b1;
        tick;
        awvalid = 1'b0;
        chk1(1503, awready, 1'b0);
        chk1(1504, bvalid, 1'b0);
        aresetn = 1'b0;
        tick;
        tick;
        aresetn = 1'b1;
        chk1(1505, awready, 1'b1);
        chk1(1506, wready, 1'b1);
        chk1(1507, arready, 1'b1);
        chk1(1508, bvalid, 1'b0);
        chk1(1509, rvalid, 1'b0);
        chk1(1510, irq, 1'b0);
        rd(1511, A_CTRL,   32'h0, OKAY);
        rd(1512, A_LOAD,   32'h0, OKAY);
        rd(1513, A_COUNT,  32'h0, OKAY);
        rd(1514, A_STATUS, 32'h0, OKAY);
        idle(40);
        chk32(1515, rise_count, base);
        chk1(1516, irq, 1'b0);
        // W alone after reset must not pair with the pre-reset address.
        wdata  = 32'h5A5A_5A5A;
        wstrb  = 4'hF;
        chk1(1517, wready, 1'b1);
        wvalid = 1'b1;
        tick;
        wvalid = 1'b0;
        chk1(1518, wready, 1'b0);
        chk1(1519, bvalid, 1'b0);
        idle(3);
        chk1(1520, bvalid, 1'b0);
        awaddr = trunc(A_LOAD);
        chk1(1521, awready, 1'b1);
        awvalid = 1'b1;
        tick;
        awvalid = 1'b0;
        chk1(1522, bvalid, 1'b1);
        chk2(1523, bresp, OKAY);
        bready = 1'b1;
        tick;
        bready = 1'b0;
        chk1(1524, bvalid, 1'b0);
        rd(1525, A_LOAD, 32'h5A5A_5A5A, OKAY);

        idle(2);
        done = 1'b1;
    end

endmodule
